:root {
  color-scheme: light;
  --canvas: var(--rhoe-canvas, #eef1ed);
  --surface: var(--rhoe-surface, #fcfdfb);
  --surface-muted: var(--rhoe-surface-muted, #e2e6e1);
  --text: var(--rhoe-text, #191b19);
  --text-secondary: var(--rhoe-text-secondary, #59605b);
  --border: var(--rhoe-border, #d9ddd9);
  --primary: var(--rhoe-primary, #252725);
  --primary-hover: var(--rhoe-primary-hover, #343734);
  --primary-foreground: var(--rhoe-primary-foreground, #f8faf8);
  --success: var(--rhoe-success, #18794e);
  --success-foreground: var(--rhoe-success-foreground, #ffffff);
  --success-surface: var(--rhoe-success-surface, #e7f6ec);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #17653f);
  --warning: var(--rhoe-warning, #946200);
  --warning-foreground: var(--rhoe-warning-foreground, #ffffff);
  --warning-surface: var(--rhoe-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #6b4600);
  --danger: var(--rhoe-danger, #b42318);
  --danger-foreground: var(--rhoe-danger-foreground, #ffffff);
  --danger-surface: var(--rhoe-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #8f1d14);
  --focus: var(--rhoe-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --duration-considered: 480ms;
  --duration-reveal: 600ms;
  --duration-expand: 720ms;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --input-expanded-duration: var(--duration-considered);
  --input-expanded-ease: var(--ease-enter);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--rhoe-canvas, #121412);
    --surface: var(--rhoe-surface, #1a1d1a);
    --surface-muted: var(--rhoe-surface-muted, #232623);
    --text: var(--rhoe-text, #f1f3f0);
    --text-secondary: var(--rhoe-text-secondary, #afb5b0);
    --border: var(--rhoe-border, #373b37);
    --primary: var(--rhoe-primary, #ecefeb);
    --primary-hover: var(--rhoe-primary-hover, #ffffff);
    --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
    --success: var(--rhoe-success, #62c98f);
    --success-foreground: var(--rhoe-success-foreground, #092416);
    --success-surface: var(--rhoe-success-surface, #173526);
    --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
    --warning: var(--rhoe-warning, #e9ad45);
    --warning-foreground: var(--rhoe-warning-foreground, #291900);
    --warning-surface: var(--rhoe-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
    --danger: var(--rhoe-danger, #ff716b);
    --danger-foreground: var(--rhoe-danger-foreground, #260503);
    --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
    --focus: var(--rhoe-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--rhoe-canvas, #121412);
  --surface: var(--rhoe-surface, #1a1d1a);
  --surface-muted: var(--rhoe-surface-muted, #232623);
  --text: var(--rhoe-text, #f1f3f0);
  --text-secondary: var(--rhoe-text-secondary, #afb5b0);
  --border: var(--rhoe-border, #373b37);
  --primary: var(--rhoe-primary, #ecefeb);
  --primary-hover: var(--rhoe-primary-hover, #ffffff);
  --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
  --success: var(--rhoe-success, #62c98f);
  --success-foreground: var(--rhoe-success-foreground, #092416);
  --success-surface: var(--rhoe-success-surface, #173526);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
  --warning: var(--rhoe-warning, #e9ad45);
  --warning-foreground: var(--rhoe-warning-foreground, #291900);
  --warning-surface: var(--rhoe-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
  --danger: var(--rhoe-danger, #ff716b);
  --danger-foreground: var(--rhoe-danger-foreground, #260503);
  --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
  --focus: var(--rhoe-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .rhoe-code-source .shiki,
html[data-theme="dark"] .rhoe-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .rhoe-code-source .shiki,
  html:not([data-theme="light"]) .rhoe-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes rhoe-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes rhoe-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes rhoe-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

@keyframes rhoe-calendar-range-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    expand: 0.72,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export type ToastTone = "neutral" | "success" | "warning" | "danger";
export type ToastVariant = "filled" | "bordered";
export type ToastFill = "tinted" | "solid";
export type ToastPosition =
  | "top-left"
  | "top-center"
  | "top-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right";

export interface ToastOptions {
  /** Visible notification text. */
  text: ReactNode;
  /** Optional leading icon. */
  icon?: ReactNode;
  /** Semantic notification color. */
  tone?: ToastTone;
  /** Filled or outlined surface. */
  variant?: ToastVariant;
  /** Tinted or solid color treatment for filled toasts. */
  fill?: ToastFill;
  /** Time in milliseconds before dismissal. Use 0 to keep it visible. */
  duration?: number;
  /** Stable identifier used to replace an existing toast. */
  id?: string;
}

interface ToastItem extends ToastOptions {
  id: string;
}

interface ToastContextValue {
  toast: (options: ToastOptions) => string;
  dismiss: (id: string) => void;
  dismissAll: () => void;
}

export interface ToastProviderProps {
  children: ReactNode;
  /** Viewport corner or edge center. */
  position?: ToastPosition;
  /** Maximum number of visible notifications. */
  stackLimit?: 1 | 2 | 3;
  /** Default dismissal delay in milliseconds. */
  duration?: number;
}

const ToastContext = createContext<ToastContextValue | null>(null);

function subscribeToPortal() {
  return () => undefined;
}

const positionClasses: Record<ToastPosition, string> = {
  "top-left": "top-4 left-4",
  "top-center": "top-4 left-1/2 -translate-x-1/2",
  "top-right": "top-4 right-4",
  "bottom-left": "bottom-4 left-4",
  "bottom-center": "bottom-4 left-1/2 -translate-x-1/2",
  "bottom-right": "right-4 bottom-4",
};

const tintedClasses: Record<ToastTone, string> = {
  neutral: "border-transparent bg-[var(--surface-muted)] text-[var(--text)]",
  success: "border-transparent bg-[var(--surface-muted)] text-[var(--success-surface-foreground)]",
  warning: "border-transparent bg-[var(--surface-muted)] text-[var(--warning-surface-foreground)]",
  danger: "border-transparent bg-[var(--surface-muted)] text-[var(--danger-surface-foreground)]",
};

const solidClasses: Record<ToastTone, string> = {
  neutral: "border-transparent bg-[var(--primary-hover)] text-[var(--text)]",
  success: "border-transparent bg-[var(--success-surface)] text-[var(--success-surface-foreground)]",
  warning: "border-transparent bg-[var(--warning-surface)] text-[var(--warning-surface-foreground)]",
  danger: "border-transparent bg-[var(--danger-surface)] text-[var(--danger-surface-foreground)]",
};

const borderedClasses: Record<ToastTone, string> = {
  neutral: "border border-[var(--border)] bg-[var(--surface)] text-[var(--text)]",
  success: "border border-[var(--success-surface-foreground)] bg-[var(--surface)] text-[var(--success-surface-foreground)]",
  warning: "border border-[var(--warning-surface-foreground)] bg-[var(--surface)] text-[var(--warning-surface-foreground)]",
  danger: "border border-[var(--danger-surface-foreground)] bg-[var(--surface)] text-[var(--danger-surface-foreground)]",
};

const STACK_PEEK = 14;
const STACK_SCALE_STEP = 0.05;
const STACK_GAP = 8;
const TOAST_MIN_HEIGHT = 96;

function ToastCard({
  item,
  index,
  expanded,
  position,
  stackHeight,
}: {
  item: ToastItem;
  index: number;
  expanded: boolean;
  position: ToastPosition;
  stackHeight: number;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const tone = item.tone ?? "neutral";
  const variant = item.variant ?? "filled";
  const fill = item.fill ?? "tinted";
  const opensDownward = position.startsWith("top");
  const direction = opensDownward ? 1 : -1;
  const offset = expanded
    ? index * (stackHeight + STACK_GAP) * direction
    : index * STACK_PEEK * direction;
  const scale = expanded ? 1 : Math.max(0.85, 1 - index * STACK_SCALE_STEP);
  const fromY = opensDownward ? -stackHeight : stackHeight;
  const appearance = variant === "bordered"
    ? borderedClasses[tone]
    : fill === "solid"
      ? solidClasses[tone]
      : tintedClasses[tone];

  return (
    <motion.li
      layout
      className={[
        "absolute inset-x-0 z-[3] pointer-events-auto flex min-h-24 items-center gap-3 rounded-[18px] border px-6 py-5 text-base leading-[1.5] font-[650] shadow-[var(--shadow-resting)]",
        opensDownward ? "top-0" : "bottom-0",
        appearance,
      ].join(" ")}
      style={{ zIndex: 10 - index }}
      role={tone === "danger" || tone === "warning" ? "alert" : "status"}
      aria-atomic="true"
      initial={reduceMotion ? { opacity: 0 } : { opacity: 0, transform: `translateY(${fromY}px) scale(0.94)` }}
      animate={{ opacity: 1, transform: `translateY(${offset}px) scale(${scale})` }}
      exit={reduceMotion ? { opacity: 0 } : { opacity: 0, transform: `translateY(${fromY}px) scale(0.96)` }}
      transition={reduceMotion ? { duration: 0.1 } : motionTokens.spring.morph}
    >
      {item.icon ? <span className="grid shrink-0 place-items-center [&>svg]:size-5" aria-hidden="true">{item.icon}</span> : null}
      <span className="min-w-0 [overflow-wrap:anywhere]">{item.text}</span>
    </motion.li>
  );
}

export function ToastProvider({
  children,
  position = "bottom-right",
  stackLimit = 3,
  duration = 4000,
}: ToastProviderProps) {
  const [items, setItems] = useState<ToastItem[]>([]);
  const [stackExpanded, setStackExpanded] = useState(false);
  const portalContainer = useSyncExternalStore(
    subscribeToPortal,
    () => document.body,
    () => null,
  );
  const idRef = useRef(0);
  const timersRef = useRef(new Map<string, ReturnType<typeof setTimeout>>());
  const safeLimit = Math.min(3, Math.max(1, stackLimit));

  const dismiss = useCallback((id: string) => {
    const timer = timersRef.current.get(id);
    if (timer) clearTimeout(timer);
    timersRef.current.delete(id);
    setItems((current) => current.filter((item) => item.id !== id));
  }, []);

  const dismissAll = useCallback(() => {
    timersRef.current.forEach(clearTimeout);
    timersRef.current.clear();
    setItems([]);
  }, []);

  const toast = useCallback((options: ToastOptions) => {
    const id = options.id ?? `rhoe-toast-${++idRef.current}`;
    const previousTimer = timersRef.current.get(id);
    if (previousTimer) clearTimeout(previousTimer);

    setItems((current) => [
      ...current.filter((item) => item.id !== id),
      { ...options, id },
    ].slice(-safeLimit));

    const timeout = options.duration ?? duration;
    if (timeout > 0) {
      timersRef.current.set(id, setTimeout(() => dismiss(id), timeout));
    }
    return id;
  }, [dismiss, duration, safeLimit]);

  useEffect(() => {
    const timers = timersRef.current;
    return () => timers.forEach(clearTimeout);
  }, []);

  useEffect(() => {
    const activeIds = new Set(items.map((item) => item.id));
    timersRef.current.forEach((timer, id) => {
      if (activeIds.has(id)) return;
      clearTimeout(timer);
      timersRef.current.delete(id);
    });
  }, [items]);

  const context = useMemo(() => ({ toast, dismiss, dismissAll }), [dismiss, dismissAll, toast]);
  const orderedItems = [...items].reverse();
  const stackHeight = TOAST_MIN_HEIGHT;
  const expandedHeight = stackHeight + Math.max(0, orderedItems.length - 1) * (stackHeight + STACK_GAP);

  return (
    <ToastContext.Provider value={context}>
      {children}
      {portalContainer ? createPortal(
        <motion.ol
          className={[
            "pointer-events-none fixed z-[220] m-0 w-[min(520px,calc(100vw-32px))] max-w-[calc(100vw-32px)] p-0 list-none",
            positionClasses[position],
          ].join(" ")}
          aria-label="Notifications"
          tabIndex={orderedItems.length > 1 ? 0 : -1}
          onClick={() => setStackExpanded((current) => !current)}
          onKeyDown={(event) => { if (event.key === "Escape") setStackExpanded(false); }}
          animate={{ height: orderedItems.length === 0 ? 0 : stackExpanded ? expandedHeight : stackHeight }}
          transition={motionTokens.spring.morph}
          onPointerEnter={(event) => {
            if (event.pointerType === "mouse") setStackExpanded(true);
          }}
          onPointerLeave={(event) => {
            if (event.pointerType === "mouse") setStackExpanded(false);
          }}
          onFocusCapture={() => setStackExpanded(true)}
          onBlurCapture={(event) => {
            if (!event.currentTarget.contains(event.relatedTarget)) setStackExpanded(false);
          }}
        >
          <AnimatePresence initial={false}>
            {orderedItems.map((item, index) => (
              <ToastCard
                key={item.id}
                expanded={stackExpanded}
                index={index}
                item={item}
                position={position}
                stackHeight={stackHeight}
              />
            ))}
          </AnimatePresence>
        </motion.ol>,
        portalContainer,
      ) : null}
    </ToastContext.Provider>
  );
}

export function useToast() {
  const context = useContext(ToastContext);
  if (!context) throw new Error("useToast must be used inside ToastProvider.");
  return context;
}
